import {
  createContext,
  useContext,
  useMemo,
  useState,
  type ReactNode,
} from "react";

import type { AuthSession, UserRole } from "@/domain/auth";
import { jwtUserInfo } from "@/lib/jwt";

type AuthState = {
  accessToken: string;
  refreshToken: string;
  tempToken: string;
  role: UserRole | null;
};

export type UserInfo = {
  email: string;
  firstName: string;
  lastName: string;
  fullName: string;
  initials: string;
};

type AuthContextValue = {
  accessToken: string;
  refreshToken: string;
  tempToken: string;
  role: UserRole | null;
  isAuthenticated: boolean;
  userInfo: UserInfo;
  setSession: (session: AuthSession) => void;
  setTempToken: (tempToken: string) => void;
  clearSession: () => void;
};

const AuthContext = createContext<AuthContextValue | undefined>(undefined);

const storageKey = "frontend.auth.session";

function readStoredSession(): AuthState {
  const fallback: AuthState = {
    accessToken: "",
    refreshToken: "",
    tempToken: "",
    role: null,
  };

  const raw = window.localStorage.getItem(storageKey);
  if (!raw) {
    return fallback;
  }

  try {
    const parsed = JSON.parse(raw) as Partial<AuthState>;
    return {
      accessToken: parsed.accessToken ?? "",
      refreshToken: parsed.refreshToken ?? "",
      tempToken: parsed.tempToken ?? "",
      role: parsed.role ?? null,
    };
  } catch {
    return fallback;
  }
}

function persistSession(state: AuthState) {
  window.localStorage.setItem(storageKey, JSON.stringify(state));
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<AuthState>(() => readStoredSession());

  const value = useMemo<AuthContextValue>(() => {
    const setSession = (session: AuthSession) => {
      const nextState: AuthState = {
        accessToken: session.accessToken,
        refreshToken: session.refreshToken,
        tempToken: "",
        role: session.role,
      };
      setState(nextState);
      persistSession(nextState);
    };

    const setTempToken = (tempToken: string) => {
      const nextState: AuthState = {
        ...state,
        tempToken,
      };
      setState(nextState);
      persistSession(nextState);
    };

    const clearSession = () => {
      const nextState: AuthState = {
        accessToken: "",
        refreshToken: "",
        tempToken: "",
        role: null,
      };
      setState(nextState);
      persistSession(nextState);
    };

    return {
      accessToken: state.accessToken,
      refreshToken: state.refreshToken,
      tempToken: state.tempToken,
      role: state.role,
      isAuthenticated: state.accessToken !== "",
      userInfo: state.accessToken ? jwtUserInfo(state.accessToken) : { email: "", firstName: "", lastName: "", fullName: "", initials: "" },
      setSession,
      setTempToken,
      clearSession,
    };
  }, [state]);

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within AuthProvider");
  }
  return context;
}

import {
  createContext,
  useContext,
  useMemo,
  useState,
  type ReactNode,
  useEffect,
} from "react";

import type { AuthSession, UserRole } from "@/domain/auth";
import { jwtUserInfo } from "@/lib/jwt";
import { setAuthRefreshHandler } from "@/services/httpClient";
import { refreshToken as refreshTokenApi } from "@/services/authService";

type AuthState = {
  accessToken: string;
  refreshToken: string;
  tempToken: string;
  role: UserRole | null;
};

export type UserInfo = {
  email: string;
  firstName: string;
  lastName: string;
  fullName: string;
  initials: string;
};

type AuthContextValue = {
  accessToken: string;
  refreshToken: string;
  tempToken: string;
  role: UserRole | null;
  isAuthenticated: boolean;
  userInfo: UserInfo;
  setSession: (session: AuthSession) => void;
  setTempToken: (tempToken: string) => void;
  clearSession: () => void;
};

const AuthContext = createContext<AuthContextValue | undefined>(undefined);

const storageKey = "frontend.auth.session";

function readStoredSession(): AuthState {
  const fallback: AuthState = {
    accessToken: "",
    refreshToken: "",
    tempToken: "",
    role: null,
  };

  const raw = window.localStorage.getItem(storageKey);
  if (!raw) {
    return fallback;
  }

  try {
    const parsed = JSON.parse(raw) as Partial<AuthState>;
    return {
      accessToken: parsed.accessToken ?? "",
      refreshToken: parsed.refreshToken ?? "",
      tempToken: parsed.tempToken ?? "",
      role: parsed.role ?? null,
    };
  } catch {
    return fallback;
  }
}

function persistSession(state: AuthState) {
  window.localStorage.setItem(storageKey, JSON.stringify(state));
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<AuthState>(() => readStoredSession());

  // Set up token refresh handler when component mounts
  useEffect(() => {
    const handleTokenRefresh = async (): Promise<string | null> => {
      if (!state.refreshToken) {
        // Clear session if no refresh token available
        const nextState: AuthState = {
          accessToken: "",
          refreshToken: "",
          tempToken: "",
          role: null,
        };
        setState(nextState);
        persistSession(nextState);
        return null;
      }

      try {
        const newSession = await refreshTokenApi({ refreshToken: state.refreshToken });
        const nextState: AuthState = {
          accessToken: newSession.accessToken,
          refreshToken: newSession.refreshToken,
          tempToken: "",
          role: newSession.role as UserRole,
        };
        setState(nextState);
        persistSession(nextState);
        return newSession.accessToken;
      } catch (error) {
        // If refresh fails, clear the session
        console.error("Token refresh failed:", error);
        const nextState: AuthState = {
          accessToken: "",
          refreshToken: "",
          tempToken: "",
          role: null,
        };
        setState(nextState);
        persistSession(nextState);
        return null;
      }
    };

    // Set up refresh handler that returns the new token
    setAuthRefreshHandler(handleTokenRefresh);
  }, [state.refreshToken]);

  const value = useMemo<AuthContextValue>(() => {
    const setSession = (session: AuthSession) => {
      const nextState: AuthState = {
        accessToken: session.accessToken,
        refreshToken: session.refreshToken,
        tempToken: "",
        role: session.role,
      };
      setState(nextState);
      persistSession(nextState);
    };

    const setTempToken = (tempToken: string) => {
      const nextState: AuthState = {
        ...state,
        tempToken,
      };
      setState(nextState);
      persistSession(nextState);
    };

    const clearSession = () => {
      const nextState: AuthState = {
        accessToken: "",
        refreshToken: "",
        tempToken: "",
        role: null,
      };
      setState(nextState);
      persistSession(nextState);
    };

    return {
      accessToken: state.accessToken,
      refreshToken: state.refreshToken,
      tempToken: state.tempToken,
      role: state.role,
      isAuthenticated: state.accessToken !== "",
      userInfo: state.accessToken ? jwtUserInfo(state.accessToken) : { email: "", firstName: "", lastName: "", fullName: "", initials: "" },
      setSession,
      setTempToken,
      clearSession,
    };
  }, [state]);

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within AuthProvider");
  }
  return context;
}

export type JwtClaims = {
  sub?: string;
  role?: string;
  firstName?: string;
  lastName?: string;
  exp?: number;
  iat?: number;
};

export function decodeJwtPayload(token: string): JwtClaims {
  try {
    const base64 = token.split(".")[1];
    if (!base64) return {};
    const json = atob(base64.replace(/-/g, "+").replace(/_/g, "/"));
    return JSON.parse(json) as JwtClaims;
  } catch {
    return {};
  }
}

export function jwtUserInfo(token: string) {
  const claims = decodeJwtPayload(token);
  const firstName = claims.firstName ?? "";
  const lastName = claims.lastName ?? "";
  const fullName = [firstName, lastName].filter(Boolean).join(" ");
  const email = claims.sub ?? "";
  const initials = [firstName[0], lastName[0]].filter(Boolean).join("").toUpperCase() || email.slice(0, 2).toUpperCase();
  return { email, firstName, lastName, fullName, initials };
}

export type JwtClaims = {
  sub?: string;
  role?: string;
  firstName?: string;
  lastName?: string;
  exp?: number;
  iat?: number;
};

export function decodeJwtPayload(token: string): JwtClaims {
  try {
    const base64 = token.split(".")[1];
    if (!base64) return {};
    const json = atob(base64.replace(/-/g, "+").replace(/_/g, "/"));
    return JSON.parse(json) as JwtClaims;
  } catch {
    return {};
  }
}

export function jwtUserInfo(token: string) {
  const claims = decodeJwtPayload(token);
  const firstName = claims.firstName ?? "";
  const lastName = claims.lastName ?? "";
  const fullName = [firstName, lastName].filter(Boolean).join(" ");
  const email = claims.sub ?? "";
  const initials = [firstName[0], lastName[0]].filter(Boolean).join("").toUpperCase() || email.slice(0, 2).toUpperCase();
  return { email, firstName, lastName, fullName, initials };
}

export function isTokenExpired(token: string, bufferMs: number = 60000): boolean {
  if (!token) return true;
  try {
    const claims = decodeJwtPayload(token);
    if (!claims.exp) return true;
    const expirationTime = claims.exp * 1000; // Convert from seconds to milliseconds
    const now = Date.now();
    return expirationTime - now <= bufferMs;
  } catch {
    return true;
  }
}

export function getTokenExpirationTime(token: string): number | null {
  try {
    const claims = decodeJwtPayload(token);
    if (!claims.exp) return null;
    return claims.exp * 1000; // Convert from seconds to milliseconds
  } catch {
    return null;
  }
}

import { env } from '@/config/env'

export class ApiError extends Error {
  status: number
  body: string

  constructor(status: number, body: string) {
    super(`Request failed with status ${status}`)
    this.status = status
    this.body = body
  }
}

export async function requestJson<T>(
  path: string,
  options: RequestInit = {},
): Promise<T> {
  const url = new URL(path, env.apiBaseUrl)
  const headers = new Headers(options.headers)

  if (!headers.has('Content-Type') && options.body) {
    headers.set('Content-Type', 'application/json')
  }

  const response = await fetch(url, {
    ...options,
    headers,
  })

  if (!response.ok) {
    const body = await response.text()
    throw new ApiError(response.status, body)
  }

  return response.json() as Promise<T>
}

import { env } from '@/config/env'

export class ApiError extends Error {
  status: number
  body: string

  constructor(status: number, body: string) {
    super(`Request failed with status ${status}`)
    this.status = status
    this.body = body
  }
}

type AuthRefreshHandler = () => Promise<string | null>

let authRefreshHandler: AuthRefreshHandler | null = null
let isRefreshing = false
let refreshPromise: Promise<string | null> | null = null

export function setAuthRefreshHandler(handler: AuthRefreshHandler | null) {
  authRefreshHandler = handler
}

export async function requestJson<T>(
  path: string,
  options: RequestInit = {},
): Promise<T> {
  const url = new URL(path, env.apiBaseUrl)
  const headers = new Headers(options.headers)

  if (!headers.has('Content-Type') && options.body) {
    headers.set('Content-Type', 'application/json')
  }

  try {
    const response = await fetch(url, {
      ...options,
      headers,
    })

    if (!response.ok) {
      // Handle 403 Forbidden - try to refresh token
      if (response.status === 403 && authRefreshHandler && !path.includes('/auth/')) {
        // Prevent multiple simultaneous refresh attempts
        if (!isRefreshing) {
          isRefreshing = true
          refreshPromise = authRefreshHandler().finally(() => {
            isRefreshing = false
            refreshPromise = null
          })
        }

        if (refreshPromise) {
          try {
            const newToken = await refreshPromise
            // Retry the original request after token refresh with the new token
            const retryHeaders = new Headers(options.headers)

            // Update the Authorization header with the new token if available
            if (newToken) {
              retryHeaders.set('Authorization', `Bearer ${newToken}`)
            }

            const retryResponse = await fetch(url, {
              ...options,
              headers: retryHeaders,
            })

            if (!retryResponse.ok) {
              const body = await retryResponse.text()
              throw new ApiError(retryResponse.status, body)
            }

            return retryResponse.json() as Promise<T>
          } catch (error) {
            // If refresh fails, throw the original error
            const body = await response.text()
            throw new ApiError(response.status, body)
          }
        }
      }

      const body = await response.text()
      throw new ApiError(response.status, body)
    }

    return response.json() as Promise<T>
  } catch (error) {
    throw error
  }
}
